        # Church attendance (curation notes): in 2024 the filter's "No" is stored as 9 in VCF0130 and VCF0130a
        # (the short form, VCF9222 -1, did not ask); in 2020 VCF0130a was built without the filter, so those who never
        # attend (VCF0130 5) are 9 there.
        year, short_form = df["VCF0004"], df["VCF9222"].astype(str).str.strip().eq("-1")
        for col in ("VCF0130", "VCF0130a"):
            filter_no = year.eq(2024) & df[col].astype(str).str.strip().eq("9") & ~short_form
            df.loc[filter_no, col] = "5"
        never = (
            year.eq(2020)
            & df["VCF0130a"].astype(str).str.strip().eq("9")
            & df["VCF0130"].astype(str).str.strip().eq("5")
        )
        df.loc[never, "VCF0130a"] = "5"
        # "All of life" is a length of residence: the respondent's age (VCF0101, 0 = NA). VCF9001 counts years in the
        # community (0-89; 99 DK/NA), VCF9002 bands years in the home.
        age = df["VCF0101"].where(df["VCF0101"].gt(0))
        years = pd.to_numeric(df["VCF9001"], errors="raise").mask(lambda v: v.eq(99))
        df["VCF9001"] = years.mask(years.eq(90), age)
        all_life = df["VCF9002"].astype(str).str.strip().eq("6")
        band = pd.cut(age, [-1, 4, 9, 19, 29, np.inf], labels=["1", "2", "3", "4", "5"]).astype(object)
        df.loc[all_life, "VCF9002"] = band[all_life]
